<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class Quotation extends Model { protected $fillable=['service_request_id','created_by','number','issued_at','valid_until','currency','subtotal','discount','tax','total','status','internal_notes','customer_notes','accepted_by']; protected $casts=['issued_at'=>'date','valid_until'=>'date','subtotal'=>'decimal:2','discount'=>'decimal:2','tax'=>'decimal:2','total'=>'decimal:2']; protected static function booted(){static::creating(function(self $m){$m->number??='QT-'.now()->year.'-'.str_pad((string)(self::whereYear('created_at',now()->year)->count()+1),6,'0',STR_PAD_LEFT);}); static::saving(fn(self $m)=>$m->recalculate());} public function recalculate():void{$this->subtotal=$this->items->sum(fn($i)=>($i->quantity*$i->unit_price)-$i->discount);$this->total=max(0,$this->subtotal-$this->discount+$this->tax);} public function request(){return $this->belongsTo(ServiceRequest::class,'service_request_id');} public function creator(){return $this->belongsTo(User::class,'created_by');} public function items(){return $this->hasMany(QuotationItem::class);} public function invoices(){return $this->hasMany(Invoice::class);} }
